#include "hunyuan-jni.cpp"
#include <cstdio>
#include <cstdlib>
int main(int argc,char **argv){if(argc<2)return 1;llama_log_set(quiet,nullptr);llama_backend_init();auto engine=std::make_unique<Engine>();auto mp=llama_model_default_params();mp.n_gpu_layers=0;mp.load_mode=LLAMA_LOAD_MODE_MMAP;engine->model=llama_model_load_from_file(argv[1],mp);if(!engine->model){std::printf("%s\n",diagnostic.c_str());return 2;}auto cp=llama_context_default_params();cp.n_ctx=512;cp.n_batch=128;cp.n_ubatch=128;cp.n_threads=3;cp.n_threads_batch=3;engine->context=llama_init_from_model(engine->model,cp);if(!engine->context)return 3;const auto *vocab=llama_model_get_vocab(engine->model);int mode=argc>2?std::atoi(argv[2]):0;std::string instruction="将以下文本翻译为中文，注意只需要输出翻译后的结果，不要额外解释：\n\nThe little horse is reading a book.";std::string prompt=mode==3?"translate to chinese: hello":mode==2?instruction:"<｜hy_begin▁of▁sentence｜><｜hy_User｜>"+instruction+(mode==1?"<｜hy_Assistant｜>":"<｜hy_place▁holder▁no▁8｜>");int n=-llama_tokenize(vocab,prompt.data(),prompt.size(),nullptr,0,mode>=2,true);std::vector<llama_token> tokens(n);llama_tokenize(vocab,prompt.data(),prompt.size(),tokens.data(),n,mode>=2,true);std::printf("mode=%d n=%d eos=%d first tokens:",mode,n,llama_vocab_eos(vocab));for(int i=0;i<std::min(n,8);i++)std::printf(" %d",tokens[i]);std::puts("");auto batch=llama_batch_get_one(tokens.data(),n);if(llama_decode(engine->context,batch)!=0)return 4;auto *sampler=llama_sampler_chain_init(llama_sampler_chain_default_params());llama_sampler_chain_add(sampler,llama_sampler_init_greedy());std::string text;std::vector<char> piece(512);for(int i=0;i<64;i++){auto token=llama_sampler_sample(sampler,engine->context,-1);if(llama_vocab_is_eog(vocab,token)){std::printf("end=%d at=%d\n",token,i);break;}int count=llama_token_to_piece(vocab,token,piece.data(),piece.size(),0,true);if(count<0){piece.resize(-count);count=llama_token_to_piece(vocab,token,piece.data(),piece.size(),0,true);}text.append(piece.data(),std::max(0,count));auto b=llama_batch_get_one(&token,1);if(llama_decode(engine->context,b)!=0)break;}std::puts(text.c_str());llama_sampler_free(sampler);return 0;}
